/* intro.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  /* ---------- intro silence detection ----------
   * The old implementation skipped a hard-coded 12 seconds, which regularly
   * ate the beginning of a track. Instead, decode the file once in a dedicated
   * AudioContext, measure short RMS windows and jump only when a run of real
   * sound follows a sustained initial silence. A failed decode simply leaves
   * the track at its natural start — no guessing, no chopped music. */
  function introKey(url) {
    return `${url}|${P.state.silenceDb}|${P.state.introMaxSec}`;
  }

  function ensureIntroTarget(url) {
    if (!url) return Promise.resolve(null);
    const key = P.introKey(url);
    if (!P.introCache.has(key)) P.introCache.set(key, P.analyzeIntro(url).catch(() => null));
    return P.introCache.get(key);
  }

  async function analyzeIntro(url) {
    if (!window.fetch || !(window.AudioContext || window.webkitAudioContext)) return null;
    const response = await fetch(url, { cache: "force-cache", credentials: "same-origin" });
    if (!response.ok) return null;
    const bytes = await response.arrayBuffer();
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    let context = null;
    try {
      context = new AudioContextClass();
      const buffer = await context.decodeAudioData(bytes);
      const sampleRate = buffer.sampleRate;
      const frameSamples = Math.max(1, Math.round(sampleRate * P.INTRO_WINDOW_SEC));
      const maxSeconds = Math.max(
        P.INTRO_MIN_QUIET_SEC + P.INTRO_MIN_SOUND_SEC,
        Math.min(buffer.duration, P.state.introMaxSec, P.INTRO_SCAN_MAX_SEC),
      );
      const threshold = Math.pow(10, Number(P.state.silenceDb) / 20);
      const channels = Array.from({ length: buffer.numberOfChannels }, (_, i) => buffer.getChannelData(i));
      let soundStart = -1;

      for (let time = 0; time < maxSeconds; time += P.INTRO_WINDOW_SEC) {
        const from = Math.floor(time * sampleRate);
        const to = Math.min(from + frameSamples, buffer.length);
        if (to <= from) break;
        let sumSquares = 0;
        let count = 0;
        for (const channel of channels) {
          for (let i = from; i < to; i++) {
            const value = channel[i];
            sumSquares += value * value;
            count++;
          }
        }
        const rms = count ? Math.sqrt(sumSquares / count) : 0;
        if (rms >= threshold) {
          if (soundStart < 0) soundStart = time;
          if (time - soundStart + P.INTRO_WINDOW_SEC >= P.INTRO_MIN_SOUND_SEC) {
            // Music that starts immediately is never an intro. Only a quiet
            // run long enough to be intentional qualifies for a skip.
            if (soundStart < P.INTRO_MIN_QUIET_SEC) return null;
            return Math.max(0, Math.round((soundStart - P.INTRO_LEAD_SEC) * 100) / 100);
          }
        } else {
          soundStart = -1;
        }
      }
      return null;
    } finally {
      if (context && typeof context.close === "function") context.close().catch(() => {});
    }
  }

  // Called for every fresh track. The token prevents a slow decode from an
  // earlier track seeking after the visitor has already moved on.
  function prepareIntro(url) {
    const token = ++P.introToken;
    P.introUserSeeked = false;
    P.ensureIntroTarget(url).then((target) => {
      if (token !== P.introToken || !P.state.current || target == null || P.introUserSeeked) return;
      // Decoding can take a moment; only a deliberate scrub by the visitor
      // should cancel the automatic jump, not natural playback progress.
      P.setTime(target);
      P.notify("intro");
    });
  }

  function applyIntroSetting(key, rawValue) {
    const n = Number(rawValue);
    if (!Number.isFinite(n)) return;
    if (key === "silenceDb") {
      P.state.silenceDb = Math.min(-12, Math.max(-60, Math.round(n)));
    } else if (key === "introMaxSec") {
      P.state.introMaxSec = Math.min(P.INTRO_SCAN_MAX_SEC, Math.max(5, Math.round(n)));
    }
    // Threshold changes make every cached result stale.
    P.introCache.clear();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }
  Object.assign(P, { introKey, ensureIntroTarget, analyzeIntro, prepareIntro, applyIntroSetting });
}
